const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const closingDate=String(input.closing_date??"").trim();
const now=new Date();
const close=new Date(closingDate);
const daysRemaining=closingDate&&!Number.isNaN(close.getTime())?Math.ceil((close-now)/86400000):null;
const overdue=milestones.filter(m=>m.status==="overdue"||m.overdue===true);
const critical=milestones.filter(m=>m.critical===true&&(m.status==="overdue"||m.overdue===true));
const incomplete=milestones.filter(m=>!["completed","complete","done"].includes(String(m.status||"").toLowerCase()));
const completed=incomplete.length===0&&milestones.length>0;
let status="blocked",nextWorkflow="WF-126",reason="";
if(blockers.length){status="blocked";reason="active closing blockers detected";}
else if(!closingDate||Number.isNaN(close.getTime())){status="milestone_data_incomplete";reason="valid closing date is missing";}
else if(critical.length){status="critical_overdue";nextWorkflow="WF-306";reason="critical closing milestone is overdue";}
else if(overdue.length){status="attention_required";nextWorkflow="WF-306";reason="one or more closing milestones are overdue";}
else if(completed){status="milestones_completed";nextWorkflow="WF-307";reason="all supplied closing milestones are complete";}
else if(daysRemaining!==null&&daysRemaining<=3){status="closing_due_soon";nextWorkflow="WF-306";reason="closing is within three days and milestones require monitoring";}
else{status="on_track";nextWorkflow="WF-306";reason="closing milestones are on track";}
const idempotencyKey=input.idempotency_key||`wf-305:${input.deal_id||"unknown"}:${input.milestone_version||input.version||1}`;
return [{json:{...input,workflow:"WF-305",workflow_name:"Closing Coordination → Critical Dates & Milestone Monitoring Controller",status,closing_monitor:{closing_date:closingDate||null,days_remaining:daysRemaining,milestone_count:milestones.length,incomplete_count:incomplete.length,overdue_count:overdue.length,critical_overdue_count:critical.length,completed,blockers},next_workflow:nextWorkflow,human_review_required:status!=="on_track",audit:{event_type:"closing_milestone_monitoring",idempotency_key:idempotencyKey,reason}}}];
